namespace {float number(jass::Real v){return std::bit_cast<float>(v.bits());}jass::Real real(float v){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(v));}template<size_t N> std::array<float,N> factors(const std::string& text,float maximum,const char* invalid,const char* missing){std::stringstream source(text);std::string part;std::array<float,N> result{};size_t count=0;while(std::getline(source,part,',')){float value=std::stof(part);if(!std::isfinite(value) || value<0 || value>maximum)throw std::runtime_error(invalid);if(count<N)result[count]=value;++count;}if(count!=N)throw std::runtime_error(missing);return result;}}
float ScriptSession::armorBasePoints(const UnitState& unit){float points=definitions().number(unit.type,"UnitBalance","def")+unit.technology.armor+unit.equipment.armor;if(unit.hero)points+=unit.appliedHeroStats[1]*gameplayNumber("AgiDefenseBonus",.3f)+gameplayNumber("AgiDefenseBase",-2);return points;}
float ScriptSession::armorPoints(const UnitState& unit,const PassiveInfo* carapace,float base){return base*(1+unit.aura.armorPercent)+unit.aura.armor+unit.spellBonus(&UnitBuff::armor)+(carapace?carapace->bonus:0);}
bool ScriptSession::damageUnit(std::uint32_t source,std::uint32_t target,float amount,unsigned attackType,unsigned damageType,bool attack,bool ranged,float* dealt,bool deflected,bool useEtherealBonus,std::optional<unsigned> orphanOwner,bool redistributed,bool diseaseAura,bool nonlethal) {
    if(dealt)*dealt=0;if(!std::isfinite(amount) || amount<0 || amount>1000000000)throw std::runtime_error("Damage amount outside supported range");if(attackType>6 || (damageType!=0 && damageType!=4 && damageType!=5 && (damageType<8 || damageType>26)))throw std::runtime_error("Unknown damage classification");if((!alive(source,NativeKind::Unit) && !orphanOwner) || !alive(target,NativeKind::Unit))return false;if(orphanOwner && *orphanOwner>=16)throw std::runtime_error("Invalid retained periodic damage owner");auto from=alive(source,NativeKind::Unit)?units_.at(source):std::shared_ptr<UnitState>{},to=units_.at(target);if(!from)source=0;auto damageOwner=from?from->owner:orphanOwner.value_or(UINT_MAX);if(to->swarmAgent || capability(*to,"Aloc") || to->impaledAir() || to->sleepProtected() || to->cycloned())return false;if((from && from->removing) || to->removing || to->concoction || to->invulnerable || to->phaseShifted() || to->mirrorImage || to->spiritSplit || (to->lavaSpawn && to->lavaSpawn->emerging) || (to->transport && !(to->digestion && source==to->transport)) || capability(*to,"Avul") || number(to->life)<=0)return false;if((!diseaseAura || gameplayNumber("MagicImmunesResistDamage",0)!=0) && capability(*to,"Amim") && damageType!=26 && (attackType==4 || (damageType>=8 && damageType<=20) || damageType==23 || damageType==25))return false;if(attack && !redistributed && !deflected && amount>0 && from){auto death=to->deathRevision;if(phaseShiftReaction(target,source) || !alive(target,NativeKind::Unit) || to->removing || to->deathRevision!=death || number(to->life)<=0 || !alive(source,NativeKind::Unit) || from->removing || from->owner!=damageOwner)return false;}double damage=redistributed?amount:double(amount)*(from?from->damageDealt:1)*to->damageTaken;if(to->ethereal() && damageType!=26){if(!etherealDamageFactors_)etherealDamageFactors_=factors<7>(gameplay().value("Misc","EtherealDamageBonus"),100,"Invalid source ethereal damage factor","Missing source ethereal damage factors");constexpr unsigned slots[]={5,0,1,2,3,4,6};float factor=(*etherealDamageFactors_)[slots[attackType]];if(factor==0)return false;if(factor>1 && !useEtherealBonus)factor=1;if(factor>1 && (damageOwner>=16 || !enemy(damageOwner,to->owner)) && gameplayNumber("EtherealDamageBonusAlly",0)==0)factor=1;damage*=factor;}
    if(damageType!=26){auto& data=definitions();auto armor=defenseType(*to);if(armor>=8)throw std::runtime_error("Unknown source defense type: "+data.field(to->type,"UnitBalance","defType","normal"));constexpr const char* attacks[]={"Spells","Normal","Pierce","Siege","Magic","Chaos","Hero"};auto& table=damageFactors_[attackType];if(!table){auto key=std::string("DamageBonus")+attacks[attackType];auto missing="Missing source attack/defense factors: "+key;table=factors<8>(gameplay().value("Misc",key),std::numeric_limits<float>::max(),"Invalid source attack factor",missing.c_str());}damage*=(*table)[armor];if(damageType==4){float defensePoints=armorBasePoints(*to);auto carapace=spikedCarapace(*to);if(carapace && attack && !ranged)damage*=carapace->secondary;defensePoints=armorPoints(*to,carapace,defensePoints);double coefficient=gameplayNumber("DefenseArmor",.06f);if(coefficient<=0 || coefficient>=1)throw std::runtime_error("Unsupported armor coefficient");damage*=defensePoints>=0?1/(1+coefficient*defensePoints):2-std::pow(1-coefficient,-defensePoints);}}
    bool spellDamage=damageType!=26 && (attackType==4 || (!attack && damageType!=4 && damageType!=5));if(!redistributed && damageType!=26)damage=defensePassiveDamage(*to,float(damage),attackType,attack,ranged,spellDamage,damageOwner,deflected);if(spellDamage)damage*=std::max(0.f,1-to->equipment.spellReduction);if(spellDamage)for(auto it=to->buffs.begin();it!=to->buffs.end();){auto& b=it->second;if(b.kind==BuffKind::Shell && !b.magicImmune){damage*=std::max(0.f,1-b.spellReduction);if(b.shield>0){float absorb=std::min(float(damage),b.shield);b.shield-=absorb;damage-=absorb;if(b.shield<=0){releaseBuff(b);it=to->buffs.erase(it);continue;}}}++it;}
    if(!redistributed){damage*=1+to->spellBonus(&UnitBuff::damageTakenBonus);for(auto& [id,b]:to->buffs)if(b.kind==BuffKind::PossessionCaster)damage*=b.damageTakenFactor;if(attack && from)for(auto& [id,b]:from->buffs)if(b.kind==BuffKind::Defend)damage*=b.attackFactor;}
    for(auto& [id,b]:to->buffs){if((b.kind==BuffKind::Avatar || b.kind==BuffKind::Bladestorm || b.kind==BuffKind::Sanctuary) && spellDamage)damage*=b.magicFactor;if(b.kind==BuffKind::Defend){if(attack && ranged && attackType==2)damage*=deflected?b.deflectPierce:b.pierceFactor;else if(deflected && attack && ranged && attackType==4)damage*=b.deflectMagic;else if(spellDamage)damage*=b.magicFactor;}}
    auto shieldMana=to->mana.bits();auto shieldDeath=to->deathRevision;auto sourceDeath=from?from->deathRevision:0;
    if(damageType!=26)for(auto it=to->buffs.begin();it!=to->buffs.end();){auto& b=it->second;if(b.kind!=BuffKind::ManaShield || b.manaEfficiency<=0 || b.absorbFraction<=0){++it;continue;}float absorbed=std::min(float(damage)*b.absorbFraction,number(to->mana)*b.manaEfficiency);to->mana=real(std::max(0.f,number(to->mana)-absorbed/b.manaEfficiency));damage-=absorbed;if(number(to->mana)<=0){releaseBuff(b);it=to->buffs.erase(it);}else ++it;}
    if(to->mana.bits()!=shieldMana){observeUnitStates(target);if(!alive(target,NativeKind::Unit) || to->removing || to->deathRevision!=shieldDeath || number(to->life)<=0 || (from && (!alive(source,NativeKind::Unit) || from->removing || from->deathRevision!=sourceDeath || from->owner!=damageOwner)))return true;}
    if(!std::isfinite(damage) || damage>1000000000)throw std::runtime_error("Final damage outside supported range");if(nonlethal)damage=std::min(damage,std::max(0.,double(number(to->life))-1));if(!redistributed && damage>0){auto revision=to->deathRevision;damage=spiritLinkDamage(source,target,float(damage),damageOwner);if(!alive(target,NativeKind::Unit) || to->removing || to->deathRevision!=revision || number(to->life)<=0)return true;}if(damage>0 && damageOwner<16 && enemy(damageOwner,to->owner))for(auto it=to->buffs.begin();it!=to->buffs.end();)if(it->second.breakOnDamage){releaseBuff(it->second);it=to->buffs.erase(it);}else ++it;auto deathRevision=to->deathRevision;ScriptContext context;context.damageSource=source;context.damageAttack=attack;context.damageRanged=ranged;context.damage=real(float(damage));unitEvent(target,UINT_MAX,52,context);if(alive(target,NativeKind::Unit) && !to->removing && to->deathRevision==deathRevision && number(to->life)>0){if(nonlethal)damage=std::min(damage,std::max(0.,double(number(to->life))-1));if(damage>0){wakeUnit(target);if(attack && !redistributed && damageOwner<16 && enemy(damageOwner,to->owner))attackAlert(*to);}if(dealt)*dealt=std::min(number(to->life),float(damage));unitLife(runtime_.handle("unit",target),real(std::max(0.f,number(to->life)-float(damage))),source);}return true;
}
bool ScriptSession::scriptDamageWidget(std::uint32_t source,std::uint32_t target,float amount,unsigned attackType,unsigned damageType,bool attack,bool ranged) {
    if(!alive(source,NativeKind::Unit) || (!alive(target,NativeKind::Unit) && !alive(target,NativeKind::Destructable) && !alive(target,NativeKind::Item)))return false;if(alive(target,NativeKind::Unit)){damageUnit(source,target,amount,attackType,damageType,attack,ranged);return true;}
    if(!std::isfinite(amount) || amount<0 || amount>1000000000)throw std::runtime_error("Damage amount outside supported range");if(attackType>6 || (damageType!=0 && damageType!=4 && damageType!=5 && (damageType<8 || damageType>26)))throw std::runtime_error("Unknown damage classification");if(units_.at(source)->removing)return true;auto attacker=units_.at(source);double adjusted=double(amount)*attacker->damageDealt;if(!std::isfinite(adjusted) || adjusted<0 || adjusted>1000000000)throw std::runtime_error("Final damage outside supported range");ScriptContext context;context.killingUnit=source;context.damageSource=source;context.damage=real(float(adjusted));context.damageAttack=attack;context.damageRanged=ranged;
    if(alive(target,NativeKind::Destructable)){auto state=destructables_.at(target);if(!state->removed && !state->invulnerable && state->life>0)destructableLife(target,std::max(0.f,state->life-float(adjusted)),context);return true;}
    if(alive(target,NativeKind::Item)){auto state=items_.at(target);if(state->invulnerable || number(state->life)<=0)return true;state->life=real(std::max(0.f,number(state->life)-float(adjusted)));if(number(state->life)<=0){auto revision=++state->lifeRevision;widgetDeath(target,context);if(alive(target,NativeKind::Item) && items_.at(target)==state && state->lifeRevision==revision && number(state->life)<=0)removeItem(target);}return true;}
    return false;
}
void ScriptSession::applyPointDamage(const PointDamage& damage) {
    if(!alive(damage.source,NativeKind::Unit) || damage.radius<0)return;struct Candidate {std::uint32_t id;std::uint64_t revision;NativeKind kind;};std::vector<Candidate> candidates;
    auto inside=[&](float x,float y,float extent){double dx=double(x)-damage.x,dy=double(y)-damage.y,radius=double(damage.radius)+std::max(0.f,extent);return dx*dx+dy*dy<=radius*radius;};
    for(auto& [id,u]:units_)if(!u->removing && !u->hidden() && number(u->life)>0 && inside(number(u->x),number(u->y),u->collision))candidates.push_back({id,u->deathRevision,NativeKind::Unit});
    for(auto& [id,d]:destructables_)if(!d->removed && d->visible && d->life>0 && inside(number(d->position.x),number(d->position.y),d->radius))candidates.push_back({id,d->lifeRevision,NativeKind::Destructable});
    for(auto& [id,item]:items_)if(!item->holder && item->visible && number(item->life)>0 && inside(number(item->x),number(item->y),0))candidates.push_back({id,item->lifeRevision,NativeKind::Item});
    std::sort(candidates.begin(),candidates.end(),[](const auto& a,const auto& b){return a.id<b.id;});
    for(const auto& candidate:candidates){if(!alive(damage.source,NativeKind::Unit))break;if(!alive(candidate.id,candidate.kind))continue;if(candidate.kind==NativeKind::Unit){auto u=units_.at(candidate.id);if(u->removing || u->deathRevision!=candidate.revision || number(u->life)<=0)continue;}else if(candidate.kind==NativeKind::Destructable){auto d=destructables_.at(candidate.id);if(d->removed || d->lifeRevision!=candidate.revision || d->life<=0)continue;}else{auto item=items_.at(candidate.id);if(item->lifeRevision!=candidate.revision || number(item->life)<=0)continue;}scriptDamageWidget(damage.source,candidate.id,damage.amount,damage.attackType,damage.damageType,damage.attack,damage.ranged);}
}
void ScriptSession::pointDamageTick(){
    while(!pointDamageQueue_.empty() && pointDamageQueue_.begin()->first<=simulationTime_){auto damage=pointDamageQueue_.begin()->second;pointDamageQueue_.erase(pointDamageQueue_.begin());applyPointDamage(damage);}
}
void ScriptSession::bindDamageNatives() {
    bind("UnitIgnoreAlarm","boolean",{"unit","boolean"},[this](auto& vm,auto a){if(!alive(a[0].bits,NativeKind::Unit))return vm.boolean(false);units_.at(a[0].bits)->ignoreAlarm=a[1].bits!=0;return vm.boolean(true);});
    bind("UnitIgnoreAlarmToggled","boolean",{"unit"},[this](auto& vm,auto a){return vm.boolean(alive(a[0].bits,NativeKind::Unit) && units_.at(a[0].bits)->ignoreAlarm);});
    bind("UnitDamageTarget","boolean",{"unit","widget","real","boolean","boolean","attacktype","damagetype","weapontype"},[this](auto& vm,auto a){if(a[7].bits>24)return vm.boolean(false);return vm.boolean(scriptDamageWidget(a[0].bits,a[1].bits,number(jass::Real::fromBits(a[2].bits)),a[5].bits,a[6].bits,a[3].bits!=0,a[4].bits!=0));});
    bind("UnitDamagePoint","boolean",{"unit","real","real","real","real","real","boolean","boolean","attacktype","damagetype","weapontype"},[this](auto& vm,auto a){
        if(!alive(a[0].bits,NativeKind::Unit) || a[8].bits>7 || a[10].bits>24)return vm.boolean(false);float delay=number(jass::Real::fromBits(a[1].bits));PointDamage damage;damage.source=a[0].bits;damage.radius=number(jass::Real::fromBits(a[2].bits));damage.x=number(jass::Real::fromBits(a[3].bits));damage.y=number(jass::Real::fromBits(a[4].bits));damage.amount=number(jass::Real::fromBits(a[5].bits));damage.attack=a[6].bits!=0;damage.ranged=a[7].bits!=0;damage.attackType=a[8].bits;damage.damageType=a[9].bits;
        if(!std::isfinite(delay) || !std::isfinite(damage.radius) || !std::isfinite(damage.x) || !std::isfinite(damage.y) || !std::isfinite(damage.amount) || damage.amount<0 || damage.amount>1000000000)throw std::runtime_error("Point damage arguments outside supported range");if(damage.attackType>6 || (damage.damageType!=0 && damage.damageType!=4 && damage.damageType!=5 && (damage.damageType<8 || damage.damageType>26)))throw std::runtime_error("Unknown damage classification");if(delay<=0)applyPointDamage(damage);else{if(pointDamageQueue_.size()>=8192)throw std::runtime_error("Point damage queue exceeds budget");auto due=simulationTime_+double(delay);if(due<=simulationTime_)due=std::nextafter(simulationTime_,std::numeric_limits<double>::infinity());pointDamageQueue_.emplace(due,damage);}return vm.boolean(true);
    });
    bind("GetEventDamage","real",{},[this](auto& vm,auto){return vm.real(contexts_.empty()?jass::Real{}:contexts_.back().damage);});
    bind("GetEventDamageSource","unit",{},[this](auto& vm,auto){return vm.handle("unit",contexts_.empty()?0:contexts_.back().damageSource);});
}
